import sys


def main():
    text = sys.stdin.read()
    if "---" in text:
        head, _, body = text.partition("---\n")
        variables = {}
        for line in head.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" not in line:
                continue
            name, value = line.split("=", 1)
            name = name.strip()
            value = value.strip()
            variables[name] = value
        processed_body = process_template(body, variables)
        sys.stdout.write(processed_body)
    else:
        sys.stdout.write(text)


def process_template(template, variables):
    result = ""
    i = 0
    while i < len(template):
        if template[i] == "{{":
            result += "{"
            i += 2
        elif template[i] == "}}":
            result += "}"
            i += 2
        elif template[i] == "{":
            j = i + 1
            while j < len(template) and template[j] != "}":
                j += 1
            if j >= len(template):
                result += "{" + template[i:]
                break
            name = template[i + 1 : j].strip()
            value = variables.get(name, "")
            result += "{" + value + "}"
            i = j + 1
        else:
            result += template[i]
            i += 1
    return result


if __name__ == "__main__":
    main()
